  "transcript": {
    "segments": [
      {
        "start": 0,
        "end": 1.48,
        "text": "因此以下各位做好的朋友"
      },
      {
        "start": 1.48,
        "end": 2.8,
        "text": "千萬不要亂唱熱歌"
      },
      {
        "start": 2.8,
        "end": 3.96,
        "text": "如果沒有音樂版權"
      },
      {
        "start": 3.96,
        "end": 5.28,
        "text": "視頻很容易被現流"
      },
      {
        "start": 5.28,
        "end": 6.64,
        "text": "下架甚至賠錢"
      },
      {
        "start": 6.64,
        "end": 8.88,
        "text": "有身視頻直接給你幹成無聲視頻"
      },
      {
        "start": 8.88,
        "end": 10.68,
        "text": "要麼只跟畫面完全不搭"
      },
      {
        "start": 10.68,
        "end": 11.72,
        "text": "以甚至也覺得"
      },
      {
        "start": 11.72,
        "end": 13.76,
        "text": "像找個剛好出眾情緒點的配樂"
      },
      {
        "start": 13.76,
        "end": 15.52,
        "text": "比找個不扣門的假方還難"
      },
      {
        "start": 15.52,
        "end": 16.36,
        "text": "前兩天"
      },
      {
        "start": 16.36,
        "end": 17.48,
        "text": "我說要同他在群裡"
      },
      {
        "start": 17.48,
        "end": 18.24,
        "text": "分享了他們最近"
      },
      {
        "start": 18.24,
        "end": 19.56,
        "text": "要用AI自己寫歌"
      },
      {
        "start": 19.56,
        "end": 20.52,
        "text": "幾分鐘一手"
      },
      {
        "start": 20.52,
        "end": 21.4,
        "text": "我聽他們推薦呢"
      },
      {
        "start": 21.4,
        "end": 22.4,
        "text": "去試一下廟下"
      },
      {
        "start": 22.4,
        "end": 24.28,
        "text": "它甚至還是細水音樂旗下的"
      },
      {
        "start": 24.28,
        "end": 25.92,
        "text": "用起來下課還是很可以的"
      },
      {
        "start": 25.92,
        "end": 27,
        "text": "可以看一下我最近做的"
      },
      {
        "start": 30,
        "end": 32.68,
        "text": "一個是鏡頭"
      },
      {
        "start": 32.68,
        "end": 36.28,
        "text": "空氣的勇敢的街頭"
      },
      {
        "start": 36.28,
        "end": 39.52,
        "text": "在城市始終的路口"
      },
      {
        "start": 39.52,
        "end": 42.16,
        "text": "一場不經意的事"
      },
      {
        "start": 42.16,
        "end": 42.68,
        "text": "怎麼樣"
      },
      {
        "start": 42.68,
        "end": 43.44,
        "text": "不錯吧"
      },
      {
        "start": 43.44,
        "end": 44.84,
        "text": "實際操作也不難"
      },
      {
        "start": 44.84,
        "end": 46.76,
        "text": "第一我主意來選擇AI做曲"
      },
      {
        "start": 46.76,
        "end": 48,
        "text": "像我剛剛那條視頻呢"
      },
      {
        "start": 48,
        "end": 49.44,
        "text": "整體分為是溫馨的"
      },
      {
        "start": 49.44,
        "end": 50.76,
        "text": "我直接為給它溫馨"
      },
      {
        "start": 50.76,
        "end": 52.16,
        "text": "柔和的關鍵詞"
      },
      {
        "start": 52.16,
        "end": 53.4,
        "text": "非常深圳出來的歌曲"
      },
      {
        "start": 53.4,
        "end": 54.96,
        "text": "會更加浪漫溫馨感"
      },
      {
        "start": 54.96,
        "end": 56.52,
        "text": "不用上什麼版所指令"
      },
      {
        "start": 56.52,
        "end": 59,
        "text": "系統會智能疲憊和試的節奏和音調"
      },
      {
        "start": 59,
        "end": 60.68,
        "text": "不一會兒曲子都出來了"
      },
      {
        "start": 60.68,
        "end": 62,
        "text": "如果你需要歌詞的話"
      },
      {
        "start": 62,
        "end": 63.44,
        "text": "可以用這個AI作詞"
      },
      {
        "start": 63.44,
        "end": 65.16,
        "text": "反正是簡單輸入想法就好"
      },
      {
        "start": 65.16,
        "end": 67.4,
        "text": "我發現它深層出來的歌詞都很有意境"
      },
      {
        "start": 67.4,
        "end": 68.52,
        "text": "如果不滿意的話"
      },
      {
        "start": 68.52,
        "end": 70.44,
        "text": "選中歌詞的情緒改就可以了"
      },
      {
        "start": 70.44,
        "end": 71.68,
        "text": "我這樣曲子做好了"
      },
      {
        "start": 71.68,
        "end": 73.36,
        "text": "不過想讓它有個環繞音效"
      },
      {
        "start": 73.36,
        "end": 75.48,
        "text": "我這邊會用它這個AI編輯器"
      },
      {
        "start": 75.48,
        "end": 78.6,
        "text": "選擇人生效果器中的300的速度環繞效果"
      },
      {
        "start": 78.6,
        "end": 81,
        "text": "完全不需要會總參數和打關鍵真"
      },
      {
        "start": 81,
        "end": 81.84,
        "text": "除此之外"
      },
      {
        "start": 81.84,
        "end": 83.24,
        "text": "這裡還有智能演唱"
      },
      {
        "start": 83.24,
        "end": 85.56,
        "text": "可以聽話音色加入智能合聲"
      },
      {
        "start": 85.56,
        "end": 86.52,
        "text": "合聲的厚度"
      },
      {
        "start": 86.52,
        "end": 87.52,
        "text": "還有各種混相"
      },
      {
        "start": 87.52,
        "end": 89,
        "text": "奧頭筒都可以調節"
      },
      {
        "start": 89,
        "end": 90.6,
        "text": "最後擋住修改拳名"
      },
      {
        "start": 90.6,
        "end": 92.2,
        "text": "可以保存也可以發行"
      },
      {
        "start": 107,
        "end": 108.4,
        "text": "AI不參與分成"
      },
      {
        "start": 108.4,
        "end": 110.03999999999999,
        "text": "這樣也不用擔心版權問題"
      },
      {
        "start": 110.03999999999999,
        "end": 111.92,
        "text": "畢竟是氣水音樂旗下出品的工具"
      },
      {
        "start": 111.92,
        "end": 112.92,
        "text": "還是比較靠譜的"
      },
      {
        "start": 112.92,
        "end": 114.52000000000001,
        "text": "現在我做視頻遇到極端"
      },
      {
        "start": 114.52000000000001,
        "end": 116.2,
        "text": "需要兵具按的時候也不加率了"
      },
      {
        "start": 116.2,
        "end": 117.24000000000001,
        "text": "想要什麼情緒"
      },
      {
        "start": 117.24000000000001,
        "end": 118.56,
        "text": "自己用廟想聲聲一條"
      },
      {
        "start": 118.56,
        "end": 119.47999999999999,
        "text": "一分鐘就搞定"
      },
      {
        "start": 119.47999999999999,
        "end": 121.2,
        "text": "半局要創作收益規劃"
      },
      {
        "start": 121.2,
        "end": 122.08,
        "text": "風格都有"
      },
      {
        "start": 122.08,
        "end": 123.64,
        "text": "成本幾乎為0"
      },
      {
        "start": 123.64,
        "end": 124.48,
        "text": "有創作需求的"
      },
      {
        "start": 124.48,
        "end": 125.72,
        "text": "還真可以去試一下"
      }
    ],
